import{_ as e,C as r,o as n,c as o,a2 as t,E as s}from"./chunks/framework.BqNd1sPY.js";const u=JSON.parse('{"title":"D13：推理、部署、RAG 与 Agent","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D13-推理、部署、RAG与Agent.md","filePath":"01-14天理论课/D13-推理、部署、RAG与Agent.md"}'),l={name:"01-14天理论课/D13-推理、部署、RAG与Agent.md"};function m(d,a,c,k,h,g){const i=r("MermaidDiagram");return n(),o("div",null,[a[0]||(a[0]=t('<h1 id="d13-推理、部署、rag-与-agent" tabindex="-1">D13：推理、部署、RAG 与 Agent <a class="header-anchor" href="#d13-推理、部署、rag-与-agent" aria-label="Permalink to &quot;D13：推理、部署、RAG 与 Agent&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>把模型放进真实系统，区分模型层、检索层、工具层和服务层。</p><h2 id="推理服务关心什么" tabindex="-1">推理服务关心什么 <a class="header-anchor" href="#推理服务关心什么" aria-label="Permalink to &quot;推理服务关心什么&quot;">​</a></h2><ul><li><strong>首 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 延迟</strong>：用户多久看到第一个输出。</li><li><strong>逐 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 延迟</strong>：后续生成速度。</li><li><strong>吞吐</strong>：单位时间服务多少 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 或请求。</li><li><strong>并发与队列</strong>：高峰时如何批处理和限流。</li><li><strong>显存与成本</strong>：权重、<a href="/LLMTrain/05-速查表/术语速查#term-kv-cache" class="wiki-term" data-wiki-title="KV Cache" data-wiki-summary="自回归生成时缓存历史 token 的 Key/Value，避免每一步重复计算。" data-wiki-misconception="KV Cache 主要用于降低训练显存。">KV Cache</a> 和工作区。</li><li><strong>可靠性</strong>：超时、重试、回滚、监控和版本管理。</li></ul><p><a href="/LLMTrain/05-速查表/术语速查#term-quantization" class="wiki-term" data-wiki-title="quantization" data-wiki-summary="用更低精度表示权重或激活，以换取更低内存和更高效率。" data-wiki-misconception="量化总能四倍加速且完全没有质量变化。">量化</a>、连续批处理、<a href="/LLMTrain/05-速查表/术语速查#term-kv-cache" class="wiki-term" data-wiki-title="KV Cache" data-wiki-summary="自回归生成时缓存历史 token 的 Key/Value，避免每一步重复计算。" data-wiki-misconception="KV Cache 主要用于降低训练显存。">KV Cache</a>、推测解码和并行可以优化不同瓶颈，但收益取决于模型、硬件、负载和实现，不能引用一个固定倍数代表所有场景。</p><h2 id="rag-先查再答" tabindex="-1">RAG：先查再答 <a class="header-anchor" href="#rag-先查再答" aria-label="Permalink to &quot;RAG：先查再答&quot;">​</a></h2>',7)),s(i,{code:"Zmxvd2NoYXJ0IFRECiAgICBRW+eUqOaIt+mXrumimF0gLS0+IFJb5qOA57SiXQogICAgRFvmlofmoaPlupNdIC0tPiBSCiAgICBSIC0tPiBDW+aKiuebuOWFs+eJh+auteaUvuWFpeS4iuS4i+aWh10KICAgIEMgLS0+IE1b5qih5Z6L55Sf5oiQXQogICAgTSAtLT4gQVvnrZTmoYjkuI7lvJXnlKhdCg=="}),a[1]||(a[1]=t('<p><a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a> 适合知识频繁变化、私有资料或需要引用的场景。失败可能来自检索没找到、切块不当、排序错误、<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>冲突或模型没有忠实使用证据。检索到文档不代表文档真实，也不保证回答忠实。</p><h2 id="agent-模型参与循环决策" tabindex="-1">Agent：模型参与循环决策 <a class="header-anchor" href="#agent-模型参与循环决策" aria-label="Permalink to &quot;Agent：模型参与循环决策&quot;">​</a></h2><p>一个简化循环：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>观察状态 -&gt; 选择工具及参数 -&gt; 执行工具 -&gt; 读取结果 -&gt; 决定继续或结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>工具调用需要结构校验、权限最小化、超时、预算、幂等性和人工确认。外部网页或文档可能包含提示注入，不能把检索文本当成可信系统指令。</p><p><a href="/LLMTrain/05-速查表/术语速查#term-agent" class="wiki-term" data-wiki-title="Agent" data-wiki-summary="让模型参与工具选择、读取结果和多步决策循环的应用结构。" data-wiki-misconception="Agent 可以脱离权限、预算和人工确认自主执行。">Agent</a> 适合步骤依赖运行结果、需要工具交互的任务。固定流程、强合规审批或简单 CRUD 往往应由普通程序主导，只在需要语言理解的节点使用模型。</p><h2 id="方法选择顺序" tabindex="-1">方法选择顺序 <a class="header-anchor" href="#方法选择顺序" aria-label="Permalink to &quot;方法选择顺序&quot;">​</a></h2><ol><li>普通代码能否可靠解决？</li><li>提示和结构化输出能否解决？</li><li>是否需要外部知识，考虑 <a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a>。</li><li>是否需要按结果动态调用工具，考虑 <a href="/LLMTrain/05-速查表/术语速查#term-agent" class="wiki-term" data-wiki-title="Agent" data-wiki-summary="让模型参与工具选择、读取结果和多步决策循环的应用结构。" data-wiki-misconception="Agent 可以脱离权限、预算和人工确认自主执行。">Agent</a>。</li><li>是否有稳定行为差距和高质量数据，考虑微调。</li><li>只有在基础模型能力不足且资源充分时，才考虑更重的训练。</li></ol><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><p>为“查询公司报销政策并提交报销”画系统图，标出检索、模型、审批、财务 API 和人工确认。指出哪些步骤绝不能仅凭模型自然语言结果直接执行。</p><p>来源：<a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">RAG</a>、<a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">ReAct</a></p><p>下一课：<a href="./D14-多模态、应用全景与总复习">D14：多模态、应用全景与总复习</a></p>',12))])}const w=e(l,[["render",m]]);export{u as __pageData,w as default};
